/* Start here entry for solar-system-formation (demos/lib/starthere/solar-system-formation.js). Generated by tools/activities.py from curriculum/start-here.json:
   edit the data, not this file. demos/lib/starthere.js loads it. */
window.VDStartHere && VDStartHere({"q":"A slowly turning cloud of gas collapses under its own gravity. Does it end up as a ball or as a flat disk?","q_es":"Una nube de gas que gira despacio se colapsa por su propia gravedad. ¿Termina como una bola o como un disco plano?","setup":"set=selSpeed~1!labBlind~0!g%3AstageSeg~collapse!g%3Apresets~nebula","do":"A cloud 5,000 AU in radius that turns once every 4 million years. Decide what shape it will end up in, then press <b>Reset</b> and <b>Play</b> and watch the picture and <b>Parcels falling, in the disk, on the Sun</b>.","do_es":"Una nube de 5,000 UA de radio que da una vuelta cada 4 millones de años. Decide qué forma tendrá al final, luego presiona <b>Reiniciar</b> e <b>Iniciar</b> y observa la imagen y <b>Parcelas cayendo, en el disco, sobre el Sol</b>.","see":"By the free fall time, 63 thousand years, the cloud has flattened into a disk about 39 AU in radius, with only 6 % of the parcels on the Sun. A parcel keeps its spin as it falls, so it turns 16,383 times faster near the center and goes round instead of falling in; along the spin axis nothing holds the gas up, so the cloud falls flat. The disk radius is R<sub>d</sub> = Ω₀²r₀⁴/GM = 39.1 AU, about the size of the planets' realm.","see_es":"Para el tiempo de caída libre, 63 mil años, la nube se ha aplanado en un disco de unas 39 UA de radio, con solo el 6 % de las parcelas sobre el Sol. Una parcela conserva su giro al caer, así que gira 16,383 veces más rápido cerca del centro y da vueltas en vez de caer; a lo largo del eje de giro nada sostiene el gas, así que la nube cae hasta quedar plana. El radio del disco es R<sub>d</sub> = Ω₀²r₀⁴/GM = 39.1 UA, más o menos el tamaño de la región de los planetas.","explore":[{"setup":"set=selSpeed~1!sP0~16!labBlind~0!g%3AstageSeg~collapse!g%3Apresets~slow","do":"<b>Slow spin</b>: the same cloud turning four times more slowly, once every 16 million years. Predict the disk's radius, then press <b>To the end</b> and read <b>Tracked parcel: distance from the axis</b>. Then pick <b>No spin</b> and press <b>To the end</b> again.","do_es":"<b>Giro lento</b>: la misma nube girando cuatro veces más despacio, una vuelta cada 16 millones de años. Predice el radio del disco, luego presiona <b>Al final</b> y lee <b>Parcela seguida: distancia al eje</b>. Después elige <b>Sin giro</b> y presiona <b>Al final</b> otra vez.","see":"The disk is only 2.44 AU in radius, 16 times smaller, because R<sub>d</sub> grows as the square of the spin: 39.1/4² = 2.44 AU. With no spin at all, every one of the 1400 parcels falls onto the Sun and no disk forms: spin is what makes the disk.","see_es":"El disco mide solo 2.44 UA de radio, 16 veces menos, porque R<sub>d</sub> crece con el cuadrado del giro: 39.1/4² = 2.44 UA. Sin ningún giro, las 1400 parcelas caen sobre el Sol y no se forma un disco: el giro es lo que hace el disco."},{"setup":"set=sL~1!sDist~1000!sPres~-4!chkNeb~0!labBlind~0!g%3AstageSeg~disk!g%3Apresets~today","do":"<b>Frost line, today's Sun</b>: read <b>Frost line (water freezes beyond)</b>. A young Sun was brighter. Predict where the line goes for a Sun four times as bright, then drag <b>Young Sun's brightness</b> to 4.0 × today's and read it again.","do_es":"<b>Línea de congelación, Sol actual</b>: lee <b>Línea de congelación (más allá el agua se congela)</b>. Un Sol joven era más brillante. Predice adónde va la línea con un Sol cuatro veces más brillante, luego arrastra <b>Brillo del Sol joven</b> hasta 4.0 × el actual y léela otra vez.","see":"The line moves from 2.37 AU to 4.73 AU, only twice as far, not four times. The disk's temperature goes as L<sup>1/4</sup>/√r, so the place where it falls to water's 182 K moves out as √L = √4 = 2. Beyond the line ice adds to the solids, and that is where the giant planets grew.","see_es":"La línea pasa de 2.37 UA a 4.73 UA, solo el doble de lejos, no cuatro veces. La temperatura del disco va como L<sup>1/4</sup>/√r, así que el lugar donde baja a los 182 K del agua se aleja como √L = √4 = 2. Más allá de la línea el hielo se suma a los sólidos, y ahí crecieron los planetas gigantes."},{"setup":"set=selSpeed~1!sF~3!labBlind~0!g%3AstageSeg~planets!g%3Apresets~heavy","do":"<b>Three times heavier disk</b>, with gas that lasts 3.0 million years. Decide whether a giant planet will form, then press <b>To the end</b> and read <b>Giant planets (cores that pulled in gas)</b> and <b>Largest icy body</b>. Then pick <b>Minimum mass disk</b> and press <b>To the end</b> again.","do_es":"<b>Disco tres veces más pesado</b>, con gas que dura 3.0 millones de años. Decide si se formará un planeta gigante, luego presiona <b>Al final</b> y lee <b>Planetas gigantes (núcleos que atrajeron gas)</b> y <b>Cuerpo helado más grande</b>. Después elige <b>Disco de masa mínima</b> y presiona <b>Al final</b> otra vez.","see":"The heavier disk makes one giant, 66.3 Earth masses at 12.3 AU: a core reached 10 Earth masses while the gas was still there and pulled it in. The minimum mass disk makes none; its largest icy body ends at 9.19 Earth masses, too small and too late. The race against the gas decides whether giants form.","see_es":"El disco más pesado forma un gigante, de 66.3 masas terrestres a 12.3 UA: un núcleo llegó a 10 masas terrestres mientras el gas seguía ahí y lo atrajo. El disco de masa mínima no forma ninguno; su cuerpo helado más grande termina con 9.19 masas terrestres, demasiado pequeño y demasiado tarde. La carrera contra el gas decide si se forman gigantes."}]});
